-- Demo data for trying out the app. Safe to remove: run remove-demo-data.sql.
--
-- Run once in Supabase → SQL Editor, AFTER you've signed up in the app and
-- created your company. Everything is attached to that company, dated around
-- the day you run it, and every row's id starts with de0de000 so the removal
-- script deletes exactly this and nothing else.

create or replace function pg_temp.mi(d date, hm time) returns text language sql immutable as $$
  select to_char(((d + hm) at time zone 'America/Detroit') at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
$$;

do $demo$
declare
  t date := (now() at time zone 'America/Detroit')::date;   -- today in Michigan
  v_org uuid;
  v_owner uuid;
  v_name text;
  v_crew jsonb;
  sig text := 'data:image/png;base64,';
  me text := 'data:image/png;base64,';
begin
  select id, name into v_org, v_name from public.organizations where deleted_at is null order by created_at limit 1;
  if v_org is null then
    raise exception 'No company yet. Sign up in the app and create your company first, then run this again.';
  end if;
  if exists (select 1 from public.jobs where id::text like 'de0de000-%' and deleted_at is null) then
    raise exception 'Demo data is already loaded. Run remove-demo-data.sql first if you want to reload it.';
  end if;
  -- Clear out demo rows from an earlier load that were removed, so this can run again.
  delete from public.payments where id::text like 'de0de000-%';
  delete from public.invoices where id::text like 'de0de000-%';
  delete from public.events where id::text like 'de0de000-%';
  delete from public.jobs where id::text like 'de0de000-%';
  delete from public.customers where id::text like 'de0de000-%';
  select user_id into v_owner from public.members where org_id = v_org and role = 'owner' and deleted_at is null order by created_at limit 1;
  v_crew := case when v_owner is null then '[]'::jsonb else jsonb_build_array(v_owner::text) end;
  raise notice 'Adding demo data to %', v_name;

  -- Contacts
  insert into public.customers (id, org_id, first_name, last_name, company, phone, email, street, town, state, zip, notes) values ('de0de000-0000-4000-8000-000000000101'::uuid, v_org, 'Nadia', 'Kowalski', '', '231-555-0101', 'nadia.k@example.com', '4120 Peninsula Dr', 'Traverse City', 'MI', '49686', 'Demo contact');
